#include <iostream>
#include <vector>

class Point {
private:
    int x{0};
    int y{0};
    int color{1};

public:
    // Default constructor
    Point() : x(0), y(0), color(1) {
        std::cout << "[Default ctor] ";
    }

    // Parameterized constructor with default color = 15
    Point(int xVal, int yVal, int colorVal = 15)
        : x(xVal), y(yVal), color(colorVal) {
        std::cout << "[Param ctor] ";
    }

    void display() const {
        std::cout << "(" << x << ", " << y << ", col: " << color << ")\n";
    }

    friend void printPoint(const Point& p) {
        std::cout << "friend: (" << p.x << ", " << p.y << ", col: " << p.color << ")\n";
    }
};

int main() {
    // 1. Single object with default constructor
    std::cout << "d1: ";
    Point d1;
    d1.display();

    // 2. Single object with parameterized constructor
    std::cout << "d2: ";
    Point d2(200, 200, 10);
    d2.display();

    // 3. Dynamic allocation with new
    std::cout << "dynamic: ";
    Point* ptr = new Point(300, 300);
    ptr->display();
    delete ptr;

    // 4. Temporary object (rvalue) calling a member method
    std::cout << "temp obj: ";
    Point(2, 2, 2).display();

    // 5. Fixed array calling default constructor 3 times
    std::cout << "array t[3]:\n";
    Point t[3];
    std::cout << "\n";
    for (int i = 0; i < 3; ++i) {
        t[i] = Point(10 + i, 20 + i, 8);
    }
    for (int i = 0; i < 3; ++i) {
        t[i].display();
    }

    return 0;
}
